def stoneGameVI(a, b):
    n = len(a)
    stones = list(zip(a, b))
    stones.sort(key=lambda x: -(x[0] + x[1]))  # sort by total value descending
    alice, bob = 0, 0
    for i, (av, bv) in enumerate(stones):
        if i % 2 == 0:
            alice += av
        else:
            bob += bv
    if alice > bob:
        return 1
    elif alice < bob:
        return -1
    else:
        return 0
